    "text": "# netatlas example: long and multi-line labels, nodes of different sizes\n#\n# A test case for diagram sizing and Auto-arrange: device labels with explicit\n# line breaks, a very long label, a long word without spaces, several cables\n# between the same two devices, long cable labels, and several labelled\n# relations between the same pair of devices. Nothing is shortened: every\n# element grows to fit its text, and Auto-arrange leaves room for the labels.\nnetatlas: 1\ntitle: Long labels and mixed node sizes\n\ngroups:\n  - id: dc\n    label: Primary data centre Frankfurt am Main, building B, second floor, cage 14 (shared with the storage team)\n    kind: site\n  - id: branch\n    label: Branch\n    kind: site\n\ndevices:\n  - id: core-a\n    label: |\n      core-a\n      Core switch A\n      (rack 12, U30-U34)\n    type: switch\n    group: dc\n    tier: 3\n    interfaces:\n      - {id: Hu1/0/49}\n      - {id: Hu1/0/50}\n      - {id: Hu1/0/51}\n      - {id: TwentyFiveGigE1/0/1}\n      - {id: TwentyFiveGigE1/0/2}\n    logical_interfaces:\n      - {id: lo0, type: loopback, ip: [10.255.0.1/32, 2001:db8:ffff::1/128]}\n  - id: core-b\n    label: |-\n      core-b\n      Core switch B\n    type: switch\n    group: dc\n    tier: 3\n    interfaces:\n      - {id: Hu1/0/49}\n      - {id: Hu1/0/50}\n      - {id: Hu1/0/51}\n      - {id: TwentyFiveGigE1/0/1}\n    logical_interfaces:\n      - {id: lo0, type: loopback, ip: 10.255.0.2/32}\n  - id: fw\n    label: Perimeter firewall cluster for the production and the pre-production environment (active/passive)\n    type: firewall\n    group: dc\n    interfaces:\n      - {id: ethernet1/1, ip: 10.10.0.1/24}\n      - {id: ethernet1/2}\n    logical_interfaces:\n      - {id: tunnel.10, type: tunnel, source: ethernet1/1, destination: br-rtr:GigabitEthernet0/0/0}\n      - {id: tunnel.20, type: tunnel, source: ethernet1/1}\n  - id: srv\n    label: s\n    type: server\n    group: dc\n    interfaces:\n      - {id: eno1, ip: 10.10.0.20/24}\n  - id: storage\n    label: netapp-aff-a400-cluster01-node01.storage.infrastructure.example.internal\n    type: storage\n    group: dc\n    interfaces:\n      - {id: e0a, ip: 10.10.0.30/24}\n  - id: br-rtr\n    label: Branch router\n    type: router\n    group: branch\n    interfaces:\n      - {id: GigabitEthernet0/0/0}\n    logical_interfaces:\n      - {id: Tunnel10, type: tunnel, source: GigabitEthernet0/0/0, destination: fw:ethernet1/1}\n      - {id: Tunnel20, type: tunnel, source: GigabitEthernet0/0/0}\n\nlinks:\n  # three parallel cables between the two core switches\n  - {id: peer-1, a: \"core-a:Hu1/0/49\", b: \"core-b:Hu1/0/49\", medium: dac, speed: 100G, label: peer link 1}\n  - {id: peer-2, a: \"core-a:Hu1/0/50\", b: \"core-b:Hu1/0/50\", medium: dac, speed: 100G, label: peer link 2}\n  - {id: peer-3, a: \"core-a:Hu1/0/51\", b: \"core-b:Hu1/0/51\", medium: fiber, speed: 100G, label: keepalive}\n  - {id: fw-a, a: \"fw:ethernet1/1\", b: \"core-a:TwentyFiveGigE1/0/1\", medium: fiber, speed: 25G}\n  - {id: fw-b, a: \"fw:ethernet1/2\", b: \"core-b:TwentyFiveGigE1/0/1\", medium: fiber, speed: 25G}\n  - id: srv-a\n    a: {device: core-a, interface: TwentyFiveGigE1/0/2, networks: [servers, servers-v6, servers-v6-legacy]}\n    b: {device: srv, interface: eno1, networks: [servers, servers-v6, servers-v6-legacy]}\n    medium: dac\n    speed: 25G\n    label: hypervisor uplink, all tenant VLANs\n  - {id: sto-b, a: core-b, b: \"storage:e0a\", medium: fiber, speed: 25G, label: iSCSI}\n  - id: wan\n    a: fw\n    b: br-rtr:GigabitEthernet0/0/0\n    medium: fiber\n    speed: 1G\n    label: \"carrier ethernet, circuit CID-2024-000173\"\n    cable: CID-2024-000173\n\nnetworks:\n  # one network per prefix; the three share VLAN 10\n  - id: servers\n    label: Server network (production)\n    cidr: 10.10.0.0/24\n    vlan: 10\n  - id: servers-v6\n    label: Server network (production, IPv6)\n    cidr: \"2001:db8:10::/64\"\n    vlan: 10\n  - id: servers-v6-legacy\n    label: Server network (production, legacy IPv6 prefix)\n    cidr: \"2001:db8:11::/64\"\n    vlan: 10\n\nrelations:\n  # four labelled relations between the same two devices, two of them nested\n  - {id: ipsec-br, protocol: ipsec, label: IKEv2 site-to-site with certificate authentication, endpoints: [fw, br-rtr], over: wan}\n  - {id: gre-br, protocol: gre, label: primary, endpoints: [\"fw:tunnel.10\", \"br-rtr:Tunnel10\"], over: ipsec-br}\n  - {id: ospf-br, protocol: ospf, label: area 0.0.0.10, endpoints: [\"fw:tunnel.10\", \"br-rtr:Tunnel10\"], over: gre-br}\n  - {id: bgp-br, protocol: ebgp, label: AS 65010 ↔ AS 65020, endpoints: [fw, br-rtr]}\n  - {id: bfd-br, protocol: bfd, label: 300 ms × 3, endpoints: [fw, br-rtr]}\n  - {id: syslog-br, protocol: syslog, direction: unidirectional, label: audit log, endpoints: [br-rtr, fw]}\n  # relations between the core switches\n  - {id: mlag-core, protocol: mlag, label: domain 1, endpoints: [core-a, core-b], over: [peer-1, peer-2]}\n  - {id: ibgp-core, protocol: ibgp, endpoints: [\"core-a:lo0\", \"core-b:lo0\"]}\n  - {id: ospf-core, protocol: ospf, label: backbone, endpoints: [core-a, core-b, fw]}\n"
